-- ==============================================
-- ARTICLE: Los Submarinos (los-submarinos)
-- ==============================================
DO $$
DECLARE
  v_admin_id UUID;
  v_articulo_id UUID;
BEGIN
  SELECT id INTO v_admin_id FROM perfiles WHERE rol_id = 1 LIMIT 1;
  IF v_admin_id IS NULL THEN
    SELECT id INTO v_admin_id FROM perfiles LIMIT 1;
  END IF;

  DELETE FROM articulos WHERE slug = 'los-submarinos';

  v_articulo_id := uuid_generate_v4();

  INSERT INTO articulos (
    id,
    autor_id,
    categoria_id,
    titulo,
    slug,
    contenido,
    extracto,
    imagen_destacada,
    estado,
    etiquetas,
    metadata
  ) VALUES (
    v_articulo_id,
    v_admin_id,
    NULL,
    'Los Submarinos',
    'los-submarinos',
    $html$<h2>📜 Descripción de Los Submarinos</h2><p><strong>Los Submarinos</strong> es un apasionante juego scout de confianza, comunicación no verbal y táctica de patrulla. En él, cada equipo forma una "tripulación" que debe navegar por el terreno de juego con los ojos vendados, confiando ciegamente en la guía silenciosa o verbal de su capitán posicionado al final de la fila.</p><hr><h3>🎲 ¿Cómo se juega Los Submarinos?</h3><ol><li><strong>Formación de la Tripulación:</strong> Cada patrulla o seisena forma una fila india tomándose firmemente de la cintura o de los hombros.</li><li><strong>La Venda del Pañolín:</strong> Todos los participantes de la fila se cubren los ojos con sus <strong>pañolines</strong> para quedar completamente a ciegas, a excepción del último participante (el Capitán del Submarino).</li><li><strong>Navegación y Objetivo:</strong> El objetivo de cada submarino es maniobrar por el campo para envolver o interceptar el centro de los submarinos rivales, evitando a su vez ser envuelto por los demás.</li><li><strong>El Código del Capitán:</strong> El capitán guía la nave utilizando comandos de voz ("¡Avante!", "¡Virar a la derecha!", "¡Detenerse!") o mediante toques táctiles en los hombros del compañero de enfrente, quienes transmiten la señal en cadena hacia el participante que encabeza la fila.</li><li><strong>Victoria:</strong> El submarino que demuestre mayor agilidad de maniobra, mantenga su fila unida y logre cercar a sus oponentes sin romper la cadena gana la ronda.</li></ol>$html$,
    'Un apasionante juego scout de confianza y coordinación donde equipos a ciegas navegan guiados por su capitán.',
    '/uploads/actividad_losSubmarinos.webp',
    'publicado',
    ARRAY['juego-de-confianza', 'trabajo-en-equipo', 'panolines', 'exterior', 'patrulla'],
    $json${"areas": ["sociabilidad", "carácter", "corporalidad"], "lugares": ["Exterior", "campo abierto"], "cantidad": "08 participantes", "duracion": "20 minutos", "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "descargas": [], "objetivos": ["Estimular la confianza", "Favorecer el trabajo en equipo", "Estimular la agilidad mental", "Fomentar la comunicación en el grupo"], "materiales": ["Pañolines"], "variaciones": "<b>Navegación Silenciosa (Código Táctil):</b> En lugar de usar la voz, el capitán transmite las órdenes mediante toques en los hombros del penúltimo jugador, transmitiendo el código en cadena: 1 toque en el hombro derecho = girar a la derecha; 1 toque en el hombro izquierdo = girar a la izquierda; 2 toques simultáneos = detenerse.<br/><br/>\n\n<b>Submarino con Recolección de Torpedos:</b> Se esparcen pelotas o globos en el terreno de juego. El primer jugador a ciegas debe ser guiado para agacharse y recoger los objetos sin colisionar con otros equipos.<br/><br/>\n\n<b>Submarinos de Flota Mixta:</b> Se unen dos seisenas o patrullas para formar un super-submarino de 8 a 10 personas, poniendo a prueba la transmisión de señales a lo largo de una cadena más extensa.<br/><br/>", "recomendaciones": "<b>Inspección del Terreno:</b> Asegurar que el área de juego esté completamente libre de baches, ramas bajas u obstáculos peligrosos para evitar tropiezos de los jugadores a ciegas.<br/><br/>\n\n<b>Lanzamientos y Contacto Seguro:</b> Velar por que los toques entre submarinos sean siempre respetuosos y envolventes. Queda strictly prohibido empujar o correr bruscamente hacia los oponentes.<br/><br/>\n\n<b>Rotación del Capitán:</b> Permitir que distintos integrantes de la patrulla asuman el rol de capitán en cada ronda para que todos experimenten tanto la conducción como la confianza de dejarse guiar.<br/><br/>", "justificacion_areas": "Los Submarinos promueve la sociabilidad al consolidar la confianza mutua y la comunicación efectiva en equipo. Desarrolla el carácter al ejercitar la serenidad, la deportividad y el liderazgo responsable ante situaciones de incertidumbre visual, y estimula la corporalidad al requerir orientación espacial, coordinación postural y marcha sincronizada.", "objetivos_educativos": [{"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "area": "Sociabilidad", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "unidad": "Tropa", "como_se_cumple": "Fortaleciendo la confianza recíproca entre todos los integrantes de la patrulla."}, {"id": "106e27af-ec7a-45fa-9295-fcef88fbef3d", "area": "Corporalidad", "texto": "Convivo constantemente en la naturaleza y participo en actividades deportivas y recreativas.", "unidad": "Clan", "como_se_cumple": "Manteniendo una condición física óptima al participar en actividades recreativas de alto rendimiento."}, {"id": "117bbf3f-7e3d-4c61-b305-821609bf2e5a", "area": "Carácter", "texto": "Contribuyo al ambiente de alegría de mi Compañía.", "unidad": "Compañía", "como_se_cumple": "Compartiendo momentos de risa fraterna durante los giros y choques suaves."}, {"id": "25b24d3a-9d47-44af-b460-680508e644f3", "area": "Carácter", "texto": "Soy alegre.", "unidad": "Compañía", "como_se_cumple": "Manteniendo una actitud positiva y resiliente ante cualquier desorientación."}, {"id": "4b2e406f-2d78-4039-9ce2-4ccb743eb553", "area": "Carácter", "texto": "Soy capaz de reírme de mis propios absurdos.", "unidad": "Avanzada", "como_se_cumple": "Promoviendo el compañerismo alegre y la autocontención en el juego."}, {"id": "4bf1e3dd-7f21-4c24-962d-9d6d64e32f25", "area": "Corporalidad", "texto": "Me gusta hacer actividades al aire libre.", "unidad": "Manada", "como_se_cumple": "Desarrollando la orientación espacial al desplazarme con pañolín en los ojos."}, {"id": "4d66ed86-48ec-4801-bd0a-e5c8d023c8cd", "area": "Carácter", "texto": "Enfrento y resuelvo mis dificultades con alegría.", "unidad": "Tropa", "como_se_cumple": "Viviendo la dinámica con deportividad y excelente ánimo en equipo."}, {"id": "58b4936a-816e-4d17-8d0a-c92d0606009d", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Tropa", "como_se_cumple": "Ejercitando la percepción auditiva y táctil en el desplazamiento en fila."}, {"id": "5abfbe81-75e4-4444-b52d-38e59e8b6ec7", "area": "Sociabilidad", "texto": "Estoy siempre disponible para ayudar a los demás, incluso cuando se trata de tareas pesadas o poco agradables.", "unidad": "Avanzada", "como_se_cumple": "Fomentando un ambiente de alta confianza y cohesión en la patrulla."}, {"id": "5cbe35dc-d15b-4070-9a36-5b0e652c7946", "area": "Sociabilidad", "texto": "Respeto las opiniones de los demás.", "unidad": "Manada", "como_se_cumple": "Guiando a mis compañeros vendados con instrucciones claras y seguras."}, {"id": "5d2d48ed-c461-4a8e-9048-cceecd3de2e2", "area": "Corporalidad", "texto": "Me gusta jugar con otros niños y niñas y respeto las reglas de los juegos.", "unidad": "Manada", "como_se_cumple": "Perfeccionando la marcha a ciegas manteniendo el equilibrio y el contacto físico."}, {"id": "6768d60a-187e-4bbf-97b9-cdc25a316030", "area": "Corporalidad", "texto": "Ayudo a preparar los juegos, excursiones y campamentos de mi patrulla y mi Tropa.", "unidad": "Tropa", "como_se_cumple": "Coordinando la velocidad de marcha sincronizada con todo el grupo."}, {"id": "7200435f-b020-46fc-b323-8249048b1d18", "area": "Corporalidad", "texto": "Participo en la organización de juegos y actividades recreativas para los demás.", "unidad": "Avanzada", "como_se_cumple": "Liderando con destreza física el movimiento envolvente de la patrulla."}, {"id": "8c1cbf88-6e1d-496b-b789-9e0b767c8814", "area": "Carácter", "texto": "Casi siempre estoy alegre.", "unidad": "Manada", "como_se_cumple": "Disfrutando con entusiasmo del juego a ciegas y riéndome de los encuentros cómicos."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "area": "Sociabilidad", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "unidad": "Compañía", "como_se_cumple": "Asumiendo con responsabilidad el liderazgo de conducción del equipo."}, {"id": "9a38e454-f93a-40a5-9f68-e500ba7e0655", "area": "Carácter", "texto": "Comparto mi alegría con mis amigos, amigos y familia.", "unidad": "Tropa", "como_se_cumple": "Demostrando templanza y buen humor durante la maniobra táctica."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "unidad": "Tropa", "como_se_cumple": "Coordinando los desplazamientos de la patrulla mediante señales no verbales."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "unidad": "Compañía", "como_se_cumple": "Manteniendo la estabilidad física y el ritmo al avanzar sin apoyo visual."}, {"id": "b5a81328-5c07-41bd-a1ea-1ed401762841", "area": "Sociabilidad", "texto": "Vivo mi libertad de un modo solidario, ejerciendo mis derechos, cumpliendo mis obligaciones y defendiendo igual derecho para los demás.", "unidad": "Clan", "como_se_cumple": "Promoviendo el respeto por los derechos y la autonomía de cada caminante durante la navegación."}, {"id": "cfa10133-c25c-4deb-aebe-a00f8fe3f7ef", "area": "Sociabilidad", "texto": "Comparto lo que tengo con mis compañeros y compañeras.", "unidad": "Manada", "como_se_cumple": "Depositando mi confianza total en el timonel de mi seisena mientras camino a ciegas."}, {"id": "d408da3c-207d-4442-a891-8f50efbeecb1", "area": "Carácter", "texto": "Enfrento las dificultades con buen ánimo.", "unidad": "Manada", "como_se_cumple": "Reaccionando con alegría y serenidad ante las sorpresas de la travesía a ciegas."}, {"id": "d5b111f1-5f6f-4716-8a02-e1826d653c59", "area": "Corporalidad", "texto": "Participo en los juegos, excursiones y campamentos que organiza mi patrulla.", "unidad": "Compañía", "como_se_cumple": "Ajustando mi postura y pasos a las señales recibidas en los hombros."}, {"id": "d716bdfb-2fea-4b96-9a46-b86d66692d45", "area": "Carácter", "texto": "Enfrento la vida con alegría y sentido del humor.", "unidad": "Clan", "como_se_cumple": "Enfrentando los desafíos complejos con optimismo, madurez y alegría serena."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "area": "Sociabilidad", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "unidad": "Compañía", "como_se_cumple": "Aceptando ser guiada a ciegas por mis compañeras en el terreno de juego."}]}$json$::jsonb
  );

