  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '8c1cbf88-6e1d-496b-b789-9e0b767c8814', 'Disfrutando con entusiasmo del juego a ciegas y riéndome de los encuentros cómicos.') ON CONFLICT DO NOTHING;
