  INSERT INTO articulo_objetivos_educativos (articulo_id, objetivo_id, como_se_cumple) VALUES (v_articulo_id, '9a38e454-f93a-40a5-9f68-e500ba7e0655', 'Demostrando templanza y buen humor durante la maniobra táctica.') ON CONFLICT DO NOTHING;
